// And groups predicates with the AND operator between them.
func And(predicates ...predicate.AlertDefinition) predicate.AlertDefinition {
	return predicate.AlertDefinition(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.AlertDefinition) predicate.AlertDefinition {
	return predicate.AlertDefinition(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.AlertDefinition) predicate.AlertDefinition {
	return predicate.AlertDefinition(sql.NotPredicates(p))
}
